// 1. Get Trigger inputs
let trigger = {};
try {
  trigger = $('Webhook Trigger').first().json?.body || {};
} catch (e) {
  trigger = {};
}

const userId = trigger.userId || 'default_user';
const connectionId = trigger.connectionId || 'Production OpenRouter';
const connectionName = trigger.connectionName || 'Production OpenRouter';
const productTag = (trigger.productTag || 'SHARED_GATEWAY').toUpperCase();
const environment = (trigger.environment || 'production').toLowerCase();

// 2. Fetch Keys from 'Fetch Workspace Keys'
let rawKeys = [];
try {
  const kNode = $('Fetch Workspace Keys').first().json;
  rawKeys = kNode.body?.data || kNode.data || [];
} catch (e) {
  rawKeys = [];
}

let totalLifetimeSpend = 0;
let totalLimit = 0;
let hasLimit = false;
let totalRemaining = 0;

const keyMap = {};
const cleanedKeys = rawKeys.map((k, idx) => {
  const usage = Number(k.usage) || 0;
  const limit = typeof k.limit === 'number' ? Number(k.limit) : null;
  const remaining = typeof k.limit_remaining === 'number' ? Number(k.limit_remaining) : (limit !== null ? Math.max(0, limit - usage) : null);

  totalLifetimeSpend += usage;
  if (limit !== null) {
    totalLimit += limit;
    hasLimit = true;
  }
  if (remaining !== null) {
    totalRemaining += remaining;
  }

  const item = {
    keyId: k.hash || k.id || `key_${idx + 1}`,
    name: (k.name || k.label || `Key ${idx + 1}`).trim(),
    label: (k.label || '').trim(),
    createdAt: k.created_at || new Date().toISOString(),
    usage: Number(usage.toFixed(4)),
    usageDaily: Number((k.usage_daily || 0).toFixed(4)),
    usageWeekly: Number((k.usage_weekly || 0).toFixed(4)),
    usageMonthly: Number((k.usage_monthly || 0).toFixed(4)),
    limit: limit !== null ? Number(limit.toFixed(2)) : null,
    remaining: remaining !== null ? Number(remaining.toFixed(2)) : null,
    disabled: Boolean(k.disabled),
    workspaceId: k.workspace_id || null,
    environment,
    productTag
  };

  if (item.keyId) keyMap[item.keyId] = item;
  if (item.name) keyMap[item.name] = item;
  if (item.label) keyMap[item.label] = item;
  return item;
});

// 3. Fetch Models from 'Http Request'
let rawModels = [];
try {
  const mNode = $('Http Request').first().json;
  rawModels = mNode.body?.data?.data || mNode.data?.data || mNode.data || mNode.body?.data || [];
} catch (e) {
  rawModels = $json?.body?.data?.data || $json?.data?.data || $json?.data || $json?.body?.data || [];
}

const topModelsBySpend = (Array.isArray(rawModels) ? rawModels : []).map(m => {
  const cost = Number(m.total_usage) || 0;
  const apiKeyId = m.api_key_id ? String(m.api_key_id).trim() : null;
  const matchedKey = apiKeyId && keyMap[apiKeyId] ? keyMap[apiKeyId] : null;
  const provider = m.model && m.model.includes('/') ? m.model.split('/')[0] : 'OpenRouter';

  return {
    model: m.model,
    name: m.model,
    provider: provider.charAt(0).toUpperCase() + provider.slice(1),
    apiKeyId,
    keyName: matchedKey ? matchedKey.name : (apiKeyId || 'Default Key'),
    keyLabel: matchedKey ? matchedKey.label : '',
    cost: Number(cost.toFixed(4)),
    requests: Number(m.request_count) || 0,
    promptTokens: Number(m.tokens_prompt) || 0,
    completionTokens: Number(m.tokens_completion) || 0,
    totalTokens: (Number(m.tokens_prompt) || 0) + (Number(m.tokens_completion) || 0)
  };
}).sort((a, b) => b.cost - a.cost);

return {
  success: true,
  userId,
  connectionId,
  connectionName,
  productTag,
  environment,
  totalUsage: Number(totalLifetimeSpend.toFixed(4)),
  creditLimit: hasLimit ? Number(totalLimit.toFixed(2)) : null,
  remainingBalance: hasLimit ? Number(totalRemaining.toFixed(2)) : null,
  keysCount: cleanedKeys.length,
  modelsCount: topModelsBySpend.length,
  cleanedKeys,
  topModelsBySpend
};

// Node 5: Deduplication & Pack into ONE MongoDB document
const input = $json;
if (!input.success) return input;

const { focusRecords, ...meta } = input;

// Deduplicate focusRecords in-memory
const seenKeys = new Set();
const deduplicatedDocs = [];
let duplicatesPrevented = 0;

for (const doc of (focusRecords || [])) {
  const dedupKey = `${meta.userId}_${doc.resourceId}`;
  if (!seenKeys.has(dedupKey)) {
    seenKeys.add(dedupKey);
    deduplicatedDocs.push(doc);
  } else {
    duplicatesPrevented++;
  }
}

// Return ONE single item - MongoDB stores this as a single document
return {
  userId: meta.userId,
  connectionId: meta.connectionId,
  connectionName: meta.connectionName,
  productTag: meta.productTag,
  environment: meta.environment,
  totalUsage: meta.totalUsage,
  creditLimit: meta.creditLimit,
  remainingBalance: meta.remainingBalance,
  operation: 'OpenRouterGatewaySync',
  recordsIngested: deduplicatedDocs.length,
  duplicatesPrevented: duplicatesPrevented,
  keysList: meta.keysList || [],
  topModelsBySpend: meta.topModelsBySpend || [],
  dateWiseTelemetry: meta.dateWiseTelemetry || [],
  focusRecords: deduplicatedDocs,
  lastSyncedAt: new Date().toISOString(),
  updatedAt: new Date().toISOString()
};
